/*
 * prog22_snake_camel_convert.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program converts strings between snake_case
 * and camelCase.
 *
 *   usage: prog22_snake_camel_convert <mode> <string>
 *
 *   <mode>   "to_camel" – convert snake_case to camelCase
 *            "to_snake" – convert camelCase to snake_case
 *
 * The original binary limited the output buffer to 1024 bytes (0x400)
 * and printed the result with `puts`.  The implementation below follows
 * the same observable behaviour, including the same error messages.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024          /* 0x400 – same limit as the original binary */

static char main_out[OUT_BUF_SIZE];

/* Convert a snake_case string to camelCase.
 *  - All letters are first forced to lower case.
 *  - An underscore causes the following alphabetic character to be
 *    upper‑cased and the underscore itself is omitted.
 *  - The result is truncated to OUT_BUF_SIZE‑1 characters and NUL‑terminated.
 */
static void to_camel(const char *src)
{
    size_t out_idx = 0;
    int capitalize_next = 0;

    while (*src && out_idx + 1 < OUT_BUF_SIZE) {
        char ch = *src++;

        if (ch == '_') {
            capitalize_next = 1;          /* skip '_' and remember to capitalize */
            continue;
        }

        /* force lower case first */
        ch = (char)tolower((unsigned char)ch);

        if (capitalize_next && isalpha((unsigned char)ch)) {
            ch = (char)toupper((unsigned char)ch);
            capitalize_next = 0;
        }

        main_out[out_idx++] = ch;
    }

    main_out[out_idx] = '\0';
}

/* Convert a camelCase string to snake_case.
 *  - Upper‑case letters are preceded by '_' (unless they are the very first
 *    character) and are converted to lower case.
 *  - All other characters are copied unchanged.
 *  - The result is truncated to OUT_BUF_SIZE‑1 characters and NUL‑terminated.
 */
static void to_snake(const char *src)
{
    size_t out_idx = 0;
    int first_char = 1;          /* true while we have not written any output yet */

    while (*src && out_idx + 1 < OUT_BUF_SIZE) {
        char ch = *src++;

        if (isupper((unsigned char)ch)) {
            if (!first_char) {
                /* insert '_' before the lower‑cased letter */
                if (out_idx + 2 >= OUT_BUF_SIZE) break;   /* ensure space for '_' and the letter */
                main_out[out_idx++] = '_';
            }
            ch = (char)tolower((unsigned char)ch);
        }

        main_out[out_idx++] = ch;
        first_char = 0;
    }

    main_out[out_idx] = '\0';
}

/* ---------------------------------------------------------------------- */
int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    if (strcmp(argv[1], "to_camel") == 0) {
        to_camel(argv[2]);
        puts(main_out);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        to_snake(argv[2]);
        puts(main_out);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
